import { chromium } from '@playwright/test';

const browser = await chromium.launch();
const page = await browser.newPage();

try {
  await page.goto('http://localhost:5178/signup', { waitUntil: 'load', timeout: 10000 });
  console.log('✓ Signup page loaded');

  // Check if step indicator is visible
  const stepText = await page.textContent('text=Step 1 of 2');
  console.log('✓ Step indicator visible:', stepText);

  // Check email field exists
  const emailInput = await page.locator('[data-testid="email-input"]');
  console.log('✓ Email field exists:', await emailInput.isVisible());

  // Check password field exists
  const passwordInput = await page.locator('[data-testid="password-input"]');
  console.log('✓ Password field exists:', await passwordInput.isVisible());

  // Fill the form
  await emailInput.fill('test@example.com');
  await passwordInput.fill('Password123');
  const confirmInput = await page.locator('[data-testid="confirm-password-input"]');
  await confirmInput.fill('Password123');
  console.log('✓ Form fields filled');

  // Click Next
  const nextButton = await page.locator('button:has-text("Next")');
  await nextButton.click();
  console.log('✓ Next button clicked');

  // Wait for step 2
  await page.waitForSelector('[data-testid="full-name-input"]', { timeout: 5000 });
  console.log('✓ Step 2 loaded');

  // Verify step indicator changed
  const stepText2 = await page.textContent('text=Step 2 of 2');
  console.log('✓ Step indicator updated:', stepText2);

  // Check full name field is visible
  const fullNameInput = await page.locator('[data-testid="full-name-input"]');
  console.log('✓ Full name field visible:', await fullNameInput.isVisible());

  // Check Back button exists
  const backButton = await page.locator('button:has-text("Back")');
  console.log('✓ Back button exists:', await backButton.count());

  // Click Back and verify we return to step 1
  await backButton.click();
  await page.waitForSelector('[data-testid="email-input"]', { timeout: 5000 });
  const stepText3 = await page.textContent('text=Step 1 of 2');
  console.log('✓ Back button works, returned to step 1:', stepText3);

  console.log('\n✅ All tests passed!');
} catch (error) {
  console.error('❌ Test failed:', error.message);
  process.exit(1);
} finally {
  await browser.close();
}
EOF
node test-signup.mjs
